using TouchPanel.Theme;

namespace TouchPanel.Config;

/// <summary>
/// Generates the first-run configuration (RF-023, AC-12): the current schema version, a single
/// default page whose geometry fits a 1024×600 monitor at 100% with no clipping, containing a
/// Label, action buttons, a Toggle, and a Gauge placeholder, plus the schema-v4 appearance defaults
/// (theme <c>dark</c>, no accent, icon pack <c>default</c>; M3-RF-841). Every widget meets the
/// ≥ 40×40 DIP touch target default (D-9/RF-031). No Slider/Sparkline widgets and no per-widget
/// appearance overrides are generated by default (T-01/T-14).
/// </summary>
public static class DefaultConfigGenerator
{
    /// <summary>Identifier of the generated default page.</summary>
    public const string DefaultPageId = "main";

    private const double Margin = 16;

    /// <summary>
    /// Creates a fresh default configuration. A new instance is returned every call so callers can
    /// mutate it (for example, edit mode geometry) without affecting other callers.
    /// </summary>
    /// <returns>A valid <see cref="PanelConfig"/> with <see cref="PanelConfig.CurrentSchemaVersion"/>.</returns>
    public static PanelConfig Create()
    {
        return new PanelConfig
        {
            SchemaVersion = PanelConfig.CurrentSchemaVersion,
            ActivePageId = DefaultPageId,

            // D-17: first run targets the primary monitor; no identity criteria are known yet, so
            // the opt-in primary fallback drives placement (always accompanied by a notification).
            Monitor = new MonitorConfig
            {
                Match = null,
                Fallback = MonitorFallback.Primary,
            },

            // D-3: always-on-top defaults off; D-4/RF-003: auto-start defaults off.
            Window = new WindowConfig { AlwaysOnTop = false },
            Startup = new StartupConfig { StartWithWindows = false },

            // RF-071: telemetry polls at the M1 ~1 Hz default; hotkeys start empty (RF-058).
            Telemetry = new TelemetryConfig { PollIntervalSeconds = TelemetryConfig.DefaultPollIntervalSeconds },
            Hotkeys = [],

            // M3-RF-841: the schema-v4 appearance defaults (dark / no accent / default icon pack).
            Appearance = new AppearanceConfig
            {
                Theme = ThemeIds.Dark,
                AccentColor = null,
                IconPack = IconPackIds.Default,
            },

            Pages = [CreateDefaultPage()],
        };
    }

    /// <summary>
    /// Creates a fresh default page (id <see cref="DefaultPageId"/>). Exposed so first-run
    /// generation and validation's empty-pages handling share one definition.
    /// </summary>
    /// <returns>A new page containing the default widget set.</returns>
    public static PageConfig CreateDefaultPage() =>
        new()
        {
            Id = DefaultPageId,
            Widgets = CreateDefaultWidgets(),
        };

    private static List<WidgetConfig> CreateDefaultWidgets()
    {
        // Column positions for the action row: four 236×120 DIP targets across 1024 DIP.
        const double rowTop = 76;
        const double rowHeight = 120;
        const double columnWidth = 236;

        return
        [
            new LabelWidgetConfig
            {
                Id = "title",
                X = Margin,
                Y = Margin,
                Width = 1024 - (2 * Margin),
                Height = 44,
                Label = "TouchPanel",
            },

            new ButtonWidgetConfig
            {
                Id = "media-play-pause",
                X = Margin,
                Y = rowTop,
                Width = columnWidth,
                Height = rowHeight,
                Label = "Play/Pause",
                Action = new MediaKeyActionConfig { Key = MediaKeyKind.PlayPause },
            },

            new ButtonWidgetConfig
            {
                Id = "volume-down",
                X = Margin + columnWidth + Margin,
                Y = rowTop,
                Width = columnWidth,
                Height = rowHeight,
                Label = "Vol -",
                Action = new VolumeActionConfig
                {
                    Mode = VolumeMode.Step,
                    Direction = VolumeDirection.Down,
                },
            },

            new ButtonWidgetConfig
            {
                Id = "volume-up",
                X = Margin + (2 * (columnWidth + Margin)),
                Y = rowTop,
                Width = columnWidth,
                Height = rowHeight,
                Label = "Vol +",
                Action = new VolumeActionConfig
                {
                    Mode = VolumeMode.Step,
                    Direction = VolumeDirection.Up,
                },
            },

            new ToggleWidgetConfig
            {
                Id = "mute-toggle",
                X = Margin + (3 * (columnWidth + Margin)),
                Y = rowTop,
                Width = columnWidth,
                Height = rowHeight,
                Label = "Mute",
                InitialOn = false,
                Action = new MuteActionConfig(),
            },

            // Gauge placeholder: the Monitoring layer (T-11) resolves the application-level sensor
            // id and reports the value as unavailable when hardware/library data is missing.
            new GaugeWidgetConfig
            {
                Id = "gauge-cpu",
                X = Margin,
                Y = rowTop + rowHeight + Margin,
                Width = 496,
                Height = 372,
                Label = "CPU",
                Sensor = "cpu.total",
                Minimum = 0,
                Maximum = 100,
            },
        ];
    }
}
